        try {
            Cipher cipher = Cipher.getInstance(DETERMINISTIC_ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(generateDeterministicKeyBytes(), "AES");

            cipher.init(Cipher.ENCRYPT_MODE, keySpec);
